from collections import defaultdict, deque

input = sys.stdin.read
data = input().split()

index = 0

def read_int():
    global index
    value = int(data[index])
    index += 1
    return value

def read_ints():
    global index
    values = []
    while index < len(data) and data[index].isdigit():
        values.append(int(data[index]))
        index += 1
    return values

def solve(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def bfs(start):
        visited = set([start])
        queue = deque([start])
        degree = defaultdict(int)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                degree[node] += 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return degree

    degree_mod3 = defaultdict(int)
    for i in range(1, n + 1):
        degree = bfs(i)
        for node, deg in degree.items():
            degree_mod3[node] = deg % 3

    for c in range(1, n + 1):
        if c == 1:
            continue
        for subset in range(1, 1 << (n - 1)):
            vertices_to_steal = [i for i in range(1, n + 1) if subset & (1 << (i - 1))]
            if len(vertices_to_steal) != c:
                continue
            new_graph = defaultdict(list)
            for a, b in edges:
                if a in vertices_to_steal or b in vertices_to_steal:
                    continue
                new_graph[a].append(b)
                new_graph[b].append(a)

